using Microsoft.EntityFrameworkCore;
namespace Movers.DAL.Persistence;

/// <summary>Idempotent upgrade: OpenAI prices on the tenant settings and the AI usage log (script 033).</summary>
public static class AiUsageSchema
{
    public static async Task Apply(MoversDbContext db)
    {
        if (db.Database.IsSqlServer()) { foreach (var batch in System.Text.RegularExpressions.Regex.Split(SqlServer, @"^\s*GO\s*$", System.Text.RegularExpressions.RegexOptions.Multiline)) await db.Database.ExecuteSqlRawAsync(batch); }
        else if (db.Database.IsNpgsql()) await db.Database.ExecuteSqlRawAsync(PostgreSql);
        // SQLite is only used for fresh test databases, which EnsureCreated builds from the current model.
    }

    public const string SqlServer = """
        IF COL_LENGTH(N'dbo.TenantOpenAiConfigurations', N'InputPricePerMillion') IS NULL
            ALTER TABLE [dbo].[TenantOpenAiConfigurations] ADD [InputPricePerMillion] DECIMAL(18,6) NULL, [CachedInputPricePerMillion] DECIMAL(18,6) NULL, [OutputPricePerMillion] DECIMAL(18,6) NULL, [TranscriptionPricePerMinute] DECIMAL(18,6) NULL;
        GO
        IF OBJECT_ID(N'dbo.AiUsageRecords', N'U') IS NULL
        BEGIN
            CREATE TABLE [dbo].[AiUsageRecords] ([SerialNo] INT IDENTITY(1,1) NOT NULL CONSTRAINT [PK_AiUsageRecords] PRIMARY KEY, [Id] UNIQUEIDENTIFIER NOT NULL, [TenantId] UNIQUEIDENTIFIER NOT NULL, [Feature] NVARCHAR(40) NOT NULL, [SalesLeadId] UNIQUEIDENTIFIER NULL, [AttachmentId] UNIQUEIDENTIFIER NULL, [Model] NVARCHAR(120) NOT NULL, [InputTokens] INT NOT NULL, [CachedInputTokens] INT NOT NULL, [OutputTokens] INT NOT NULL, [TranscriptionModel] NVARCHAR(120) NULL, [AudioSeconds] DECIMAL(12,1) NOT NULL, [VisionCost] DECIMAL(18,6) NULL, [TranscriptionCost] DECIMAL(18,6) NULL, [TotalCost] DECIMAL(18,6) NULL, [Currency] NVARCHAR(3) NOT NULL, [CreatedBy] NVARCHAR(254) NOT NULL, [CreatedAtUtc] DATETIMEOFFSET NOT NULL,
                CONSTRAINT [FK_AiUsageRecords_Tenants] FOREIGN KEY ([TenantId]) REFERENCES [dbo].[Tenants]([Id]));
            CREATE UNIQUE INDEX [IX_AiUsageRecords_Id] ON [dbo].[AiUsageRecords]([Id]);
            CREATE INDEX [IX_AiUsageRecords_SalesLeadId] ON [dbo].[AiUsageRecords]([SalesLeadId]);
            CREATE INDEX [IX_AiUsageRecords_TenantId] ON [dbo].[AiUsageRecords]([TenantId]);
        END
        """;

    public const string PostgreSql = """
        ALTER TABLE "TenantOpenAiConfigurations" ADD COLUMN IF NOT EXISTS "InputPricePerMillion" numeric(18,6) NULL, ADD COLUMN IF NOT EXISTS "CachedInputPricePerMillion" numeric(18,6) NULL, ADD COLUMN IF NOT EXISTS "OutputPricePerMillion" numeric(18,6) NULL, ADD COLUMN IF NOT EXISTS "TranscriptionPricePerMinute" numeric(18,6) NULL;
        CREATE TABLE IF NOT EXISTS "AiUsageRecords" ("SerialNo" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Id" uuid NOT NULL, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "Feature" varchar(40) NOT NULL, "SalesLeadId" uuid NULL, "AttachmentId" uuid NULL, "Model" varchar(120) NOT NULL, "InputTokens" integer NOT NULL, "CachedInputTokens" integer NOT NULL, "OutputTokens" integer NOT NULL, "TranscriptionModel" varchar(120) NULL, "AudioSeconds" numeric(12,1) NOT NULL, "VisionCost" numeric(18,6) NULL, "TranscriptionCost" numeric(18,6) NULL, "TotalCost" numeric(18,6) NULL, "Currency" varchar(3) NOT NULL, "CreatedBy" varchar(254) NOT NULL, "CreatedAtUtc" timestamp with time zone NOT NULL);
        CREATE UNIQUE INDEX IF NOT EXISTS "IX_AiUsageRecords_Id" ON "AiUsageRecords"("Id");
        CREATE INDEX IF NOT EXISTS "IX_AiUsageRecords_SalesLeadId" ON "AiUsageRecords"("SalesLeadId");
        CREATE INDEX IF NOT EXISTS "IX_AiUsageRecords_TenantId" ON "AiUsageRecords"("TenantId");
        """;
}
